#include <iostream>
#include "tiling/matmul/matmul_tiling.h"

int main()
{
    using namespace matmul_tiling;
    int m, n, k, om, on, ka, kb, fm, fn, fk, l1, l0c, ub, dtype, apos, cpos;
    int batches, seq1, seq2, n2, g, stage, batch_mode, same, unsplit;
    while (std::cin >> m >> n >> k >> om >> on >> ka >> kb >> fm >> fn >> fk >> l1 >> l0c >> ub
                    >> dtype >> apos >> cpos >> batches >> seq1 >> seq2 >> n2 >> g >> stage
                    >> batch_mode >> same >> unsplit) {
        PlatformInfo platform;
        platform.socVersion = platform_ascendc::SocVersion::ASCEND910B;
        platform.l1Size = l1;
        platform.l0CSize = l0c;
        platform.l0ASize = 64 * 1024;
        platform.l0BSize = 64 * 1024;
        platform.ubSize = ub;
        MatmulApiTiling mm(platform);
        auto dt = dtype == 2 ? DataType::DT_BF16 : DataType::DT_FLOAT16;
        mm.SetAType(apos ? TPosition::VECCALC : TPosition::GM, apos ? CubeFormat::NZ : CubeFormat::ND, dt, false);
        mm.SetBType(TPosition::GM, CubeFormat::ND, dt, stage == 1);
        mm.SetCType(TPosition::GM, CubeFormat::ND, cpos ? dt : DataType::DT_FLOAT);
        mm.SetShape(m, n, k);
        mm.SetOrgShape(om, on, ka, kb);
        if (batch_mode) {
            mm.SetALayout(batches, seq1, n2, g, stage == 1 ? k : seq2);
            mm.SetBLayout(batches, seq2, n2, 1, stage == 1 ? k : n);
            mm.SetCLayout(batches, seq1, n2, g, stage == 1 ? seq2 : n);
            mm.SetBatchNum(n2 * g);
        }
        mm.SetBias(false);
        mm.SetBufferSpace(l1, l0c);
        if (fm > 0 || fn > 0 || fk > 0) {
            mm.SetFixSplit(fm, fn, fk);
        }
        AscendC::tiling::TCubeTiling t{};
        if (mm.GetTiling(t) == -1) {
            std::cout << "ERROR" << std::endl;
            continue;
        }
        if (same && stage == 1 && t.baseK >= t.singleCoreK && t.depthA1 == 2) {
            t.depthA1 = 3;
        }
        if (unsplit && stage == 1) {
            t.baseK = ((k / 2 + 15) / 16) * 16;
            t.dbL0C = 2;
        }
        std::cout << t.baseM << ' ' << t.baseN << ' ' << t.baseK << ' ' << t.depthA1 << ' '
                  << t.depthB1 << ' ' << t.dbL0C << ' ' << t.stepM << ' ' << t.stepN << ' '
                  << t.dbL0A << ' ' << t.dbL0B << ' ' << t.stepKa << ' ' << t.stepKb << ' '
                  << t.iterateOrder << ' ' << t.transLength << std::endl;
    }
}

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>

extern "C" int fa_latency_order(int n, const int32_t *a, const int32_t *b, int32_t *order)
{
    std::vector<int> degree(n, 0), offsets(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        if (a[i] >= 0) { ++degree[i]; ++offsets[a[i] + 1]; }
        if (b[i] >= 0) { ++degree[i]; ++offsets[b[i] + 1]; }
    }
    for (int i = 1; i <= n; ++i) offsets[i] += offsets[i - 1];
    auto cursor = offsets;
    std::vector<int> children(offsets[n]);
    for (int i = 0; i < n; ++i) {
        if (a[i] >= 0) children[cursor[a[i]]++] = i;
        if (b[i] >= 0) children[cursor[b[i]]++] = i;
    }
    int end = 0;
    for (int i = 0; i < n; ++i) if (!degree[i]) order[end++] = i;
    for (int at = 0; at < end; ++at) {
        const int node = order[at];
        for (int j = offsets[node]; j < offsets[node + 1]; ++j) {
            if (--degree[children[j]] == 0) order[end++] = children[j];
        }
    }
    return end;
}

extern "C" double fa_latency_eval(int n, int templates, int dimensions, int root,
    const int32_t *a, const int32_t *b, const int32_t *which,
    const double *matrix, const double *rates, double *gradient)
{
    std::vector<double> duration(templates, 0.0), finish(n, 0.0);
    std::vector<int> parent(gradient ? n : 0, -1);
    for (int t = 0; t < templates; ++t) {
        for (int j = 0; j < dimensions; ++j) duration[t] += matrix[t * dimensions + j] * rates[j];
    }
    for (int i = 0; i < n; ++i) {
        const double left = a[i] < 0 ? 0.0 : finish[a[i]];
        const double right = b[i] < 0 ? 0.0 : finish[b[i]];
        finish[i] = std::max(left, right) + duration[which[i]];
        if (gradient) parent[i] = left >= right ? a[i] : b[i];
    }
    if (gradient) {
        std::vector<double> counts(templates, 0.0);
        for (int node = root; node >= 0; node = parent[node]) ++counts[which[node]];
        for (int j = 0; j < dimensions; ++j) {
            gradient[j] = 0.0;
            for (int t = 0; t < templates; ++t) gradient[j] += counts[t] * matrix[t * dimensions + j];
        }
    }
    return finish[root];
}

